'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { fetchDocuments, createDocument, deleteDocument, DocumentItem } from '@/lib/api';
import Navbar from '@/components/Navbar';
import FileUploadModal from '@/components/FileUploadModal';
import { Plus, Upload, FileText, Trash2, Share2, Clock, ShieldCheck } from 'lucide-react';

export default function Dashboard() {
  const router = useRouter();
  const [currentUserId, setCurrentUserId] = useState('user_1');
  const [documents, setDocuments] = useState<DocumentItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [isUploadOpen, setIsUploadOpen] = useState(false);
  const [newDocTitle, setNewDocTitle] = useState('');

  const loadDocs = async (userId: string) => {
    try {
      setLoading(true);
      const data = await fetchDocuments(userId);
      setDocuments(data);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching documents:', error);
      setLoading(false);
    }
  };

  useEffect(() => {
    loadDocs(currentUserId);
  }, [currentUserId]);

  const handleCreateNew = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const doc = await createDocument(newDocTitle || 'Untitled Document', currentUserId);
      setNewDocTitle('');
      router.push(`/editor/${doc._id}`);
    } catch (error) {
      console.error('Error creating document:', error);
    }
  };

  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Are you sure you want to delete this document?')) {
      try {
        await deleteDocument(id);
        loadDocs(currentUserId);
      } catch (error) {
        console.error('Error deleting document:', error);
      }
    }
  };

  // Separate owned vs shared documents
  const ownedDocs = documents.filter((d) => d.ownerId === currentUserId);
  const sharedDocs = documents.filter((d) => d.ownerId !== currentUserId);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Navbar currentUserId={currentUserId} onUserChange={setCurrentUserId} />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 flex-1 w-full">
        
        {/* Action Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-8">
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight">Your Workspace</h2>
            <p className="text-xs text-slate-500 mt-0.5">Manage, create, or collaborate on your documents in real time.</p>
          </div>

          <div className="flex items-center space-x-3">
            <button
              onClick={() => setIsUploadOpen(true)}
              className="inline-flex items-center space-x-2 bg-white border border-slate-200 text-slate-700 px-4 py-2.5 rounded-xl text-xs font-bold shadow-sm hover:bg-slate-50 transition-colors"
            >
              <Upload className="w-4 h-4 text-indigo-600" />
              <span>Import File (.txt / .md)</span>
            </button>

            <form onSubmit={handleCreateNew} className="flex items-center space-x-2">
              <input
                type="text"
                placeholder="Document title..."
                value={newDocTitle}
                onChange={(e) => setNewDocTitle(e.target.value)}
                className="bg-white border border-slate-200 text-xs px-3 py-2.5 rounded-xl text-slate-800 focus:outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
              />
              <button
                type="submit"
                className="inline-flex items-center space-x-1.5 bg-indigo-600 text-white px-4 py-2.5 rounded-xl text-xs font-bold shadow-sm hover:bg-indigo-700 transition-colors"
              >
                <Plus className="w-4 h-4" />
                <span>New Doc</span>
              </button>
            </form>
          </div>
        </div>

        {loading ? (
          <div className="text-center py-20 text-xs font-semibold text-slate-400">Loading documents...</div>
        ) : (
          <div className="space-y-8">
            
            {/* Owned Documents Section */}
            <div>
              <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 flex items-center space-x-2">
                <ShieldCheck className="w-4 h-4 text-indigo-600" />
                <span>Owned Documents ({ownedDocs.length})</span>
              </h3>

              {ownedDocs.length === 0 ? (
                <div className="bg-white border border-slate-200 rounded-2xl p-8 text-center text-slate-400 text-xs">
                  No documents found. Create your first document above!
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                  {ownedDocs.map((doc) => (
                    <div
                      key={doc._id}
                      onClick={() => router.push(`/editor/${doc._id}`)}
                      className="bg-white border border-slate-200/80 rounded-2xl p-5 shadow-sm hover:shadow-md hover:border-indigo-300 transition-all cursor-pointer flex flex-col justify-between group"
                    >
                      <div>
                        <div className="flex items-start justify-between mb-3">
                          <div className="bg-indigo-50 p-2.5 rounded-xl text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                            <FileText className="w-5 h-5" />
                          </div>
                          <button
                            onClick={(e) => handleDelete(doc._id, e)}
                            className="text-slate-300 hover:text-rose-500 p-1.5 rounded-lg transition-colors"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                        <h4 className="text-sm font-bold text-slate-900 group-hover:text-indigo-600 transition-colors line-clamp-1">
                          {doc.title}
                        </h4>
                        <p className="text-xs text-slate-500 line-clamp-2 mt-1">
                          {doc.content || 'Empty document...'}
                        </p>
                      </div>

                      <div className="flex items-center justify-between mt-4 pt-3 border-t border-slate-100 text-[11px] text-slate-400 font-medium">
                        <span className="flex items-center space-x-1">
                          <Clock className="w-3.5 h-3.5" />
                          <span>{new Date(doc.updatedAt).toLocaleDateString()}</span>
                        </span>
                        <span className="bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded-md font-semibold text-[10px]">Owner</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Shared With Me Section */}
            <div>
              <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 flex items-center space-x-2">
                <Share2 className="w-4 h-4 text-amber-600" />
                <span>Shared With Me ({sharedDocs.length})</span>
              </h3>

              {sharedDocs.length === 0 ? (
                <div className="bg-white border border-slate-200 rounded-2xl p-8 text-center text-slate-400 text-xs">
                  No documents have been shared with {currentUserId} yet. Switch user or share a doc to test!
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                  {sharedDocs.map((doc) => (
                    <div
                      key={doc._id}
                      onClick={() => router.push(`/editor/${doc._id}`)}
                      className="bg-white border border-amber-200/80 rounded-2xl p-5 shadow-sm hover:shadow-md hover:border-amber-400 transition-all cursor-pointer flex flex-col justify-between group"
                    >
                      <div>
                        <div className="flex items-start justify-between mb-3">
                          <div className="bg-amber-50 p-2.5 rounded-xl text-amber-600 group-hover:bg-amber-600 group-hover:text-white transition-colors">
                            <FileText className="w-5 h-5" />
                          </div>
                          <span className="text-[10px] font-bold bg-amber-100 text-amber-800 px-2 py-0.5 rounded-md">Shared</span>
                        </div>
                        <h4 className="text-sm font-bold text-slate-900 group-hover:text-amber-700 transition-colors line-clamp-1">
                          {doc.title}
                        </h4>
                        <p className="text-xs text-slate-500 line-clamp-2 mt-1">
                          {doc.content || 'Empty document...'}
                        </p>
                      </div>

                      <div className="flex items-center justify-between mt-4 pt-3 border-t border-slate-100 text-[11px] text-slate-400 font-medium">
                        <span>By: {doc.ownerId}</span>
                        <span>{new Date(doc.updatedAt).toLocaleDateString()}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

          </div>
        )}
      </main>

      <FileUploadModal
        isOpen={isUploadOpen}
        onClose={() => setIsUploadOpen(false)}
        currentUserId={currentUserId}
        onSuccess={() => loadDocs(currentUserId)}
      />
    </div>
  );
}